import{_ as n,y as s,a,o as i,a2 as t,D as o}from"./chunks/framework.DCcmcJcL.js";const f=JSON.parse('{"title":"Order Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/orders-settings.md","filePath":"configure/orders-settings.md","lastUpdated":1789441803000}'),d={name:"configure/orders-settings.md"};function l(h,e,g,c,m,u){const r=s("ImagePopup");return i(),a("div",null,[e[0]||(e[0]=t('<h1 id="order-settings" tabindex="-1">Order Settings <a class="header-anchor" href="#order-settings" aria-label="Permalink to &quot;Order Settings&quot;">​</a></h1><p>These settings decide how order numbers are built, the smallest order total a customer can check out with, whether an order can be placed again, and how many times the store tries to create an order.</p><h2 id="order-numbers" tabindex="-1">Order numbers <a class="header-anchor" href="#order-numbers" aria-label="Permalink to &quot;Order numbers&quot;">​</a></h2><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Order Settings</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Order Number Settings</strong>, fill in the settings described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',4)),o(r,{src:"/images/configure/order-settings-numbers.png",alt:"Order Number Settings and Minimum Order Settings sections of the Order Settings screen"}),e[1]||(e[1]=t('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Order Number Prefix</strong></td><td>Text at the start of every order number, such as <code>ORD-</code>.</td></tr><tr><td><strong>Order Number Length</strong></td><td>How many digits the running number is padded to with zeros, from <code>1</code> to <code>10</code>.</td></tr><tr><td><strong>Order Number Suffix</strong></td><td>Text at the end of every order number.</td></tr><tr><td><strong>Order Number Generator</strong></td><td>Leave it empty unless a developer has built a custom number generator for your store.</td></tr></tbody></table><p>With a prefix of <code>ORD-</code> and a length of <code>6</code>, orders are numbered like <code>ORD-000042</code>. The running number continues from the last order in the store and is shared by all channels, so a change here affects new orders only. These settings are per channel.</p><h2 id="minimum-order-amount" tabindex="-1">Minimum order amount <a class="header-anchor" href="#minimum-order-amount" aria-label="Permalink to &quot;Minimum order amount&quot;">​</a></h2><p>A minimum order amount stops shoppers from checking out until their cart reaches that amount.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Order Settings</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Minimum Order Settings</strong>, switch <strong>Enable</strong> on. The other settings appear.</li><li>Fill in the settings described below.</li><li>Click <strong>Save Configuration</strong>.</li></ol><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enable</strong></td><td>Turns the minimum order amount on.</td></tr><tr><td><strong>Minimum Order Amount</strong></td><td>The smallest cart total a shopper can check out with. Enter a whole amount, such as <code>50</code>, because decimal places are ignored. Required while <strong>Enable</strong> is on.</td></tr><tr><td><strong>Include Discount Amount</strong></td><td>Checks the cart total after discounts.</td></tr><tr><td><strong>Include Tax to Amount</strong></td><td>Adds tax to the cart total before it&#39;s checked.</td></tr><tr><td><strong>Description</strong></td><td>The message shown on the cart page while the cart is below the minimum, followed by the amount. If it&#39;s empty, shoppers see <strong>Minimum order amount is:</strong> and the amount.</td></tr></tbody></table><p><strong>Minimum Order Amount</strong> and <strong>Description</strong> are per channel. The three switches apply to the whole store. After you change <strong>Include Discount Amount</strong> or <strong>Include Tax to Amount</strong>, check the minimum with a test cart.</p><p>While the cart is below the minimum, shoppers can&#39;t go to checkout or place the order. The same check applies to <a href="./../orders/create-order.html#settings-that-affect-admin-orders">orders you create in the admin panel</a>.</p><h2 id="allow-reorder" tabindex="-1">Allow reorder <a class="header-anchor" href="#allow-reorder" aria-label="Permalink to &quot;Allow reorder&quot;">​</a></h2><p><strong>Admin Reorder</strong> adds a <strong>Reorder</strong> button to orders in the admin panel, and <strong>Shop Reorder</strong> adds one to a customer&#39;s orders on the storefront. Both are on in a new store.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Order Settings</strong>.</li><li>In <strong>Allow Reorder</strong>, switch <strong>Admin Reorder</strong> on or off.</li><li>Switch <strong>Shop Reorder</strong> on or off.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',11)),o(r,{src:"/images/configure/order-settings-reorder.png",alt:"Allow Reorder and Order Creation sections of the Order Settings screen"}),e[2]||(e[2]=t('<ul><li><strong>In the admin panel</strong>, <strong>Reorder</strong> opens <a href="./../orders/create-order.html">Create Order</a> for the same customer, with the order&#39;s products in the cart. See <a href="./../orders/orders.html#actions-on-an-order">Actions on an order</a>.</li><li><strong>On the storefront</strong>, <strong>Reorder</strong> adds the order&#39;s products to the customer&#39;s cart and opens the cart page. See <a href="./../customer/customer-account.html#orders">Customer Account</a>.</li></ul><p>The button appears only on orders placed by a registered customer, and only while the ordered products can still be bought. Booking products are left out and have to be booked again. In the admin panel, only users allowed to create orders see the button. Both switches apply to the whole store.</p><h2 id="order-creation" tabindex="-1">Order creation <a class="header-anchor" href="#order-creation" aria-label="Permalink to &quot;Order creation&quot;">​</a></h2><p><strong>Max Retry Attempts</strong> is how many times, in total, the store tries to create an order before it gives up, for example when two orders placed at the same moment get the same number. It applies at checkout and to orders you create in the admin panel.</p><ol><li>Go to <strong>Configure &gt;&gt; Sales &gt;&gt; Order Settings</strong>.</li><li>If your store has more than one channel, choose the channel at the top of the screen.</li><li>In <strong>Order Creation</strong>, enter the <strong>Max Retry Attempts</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol><p>The default is <code>3</code>, and the setting is per channel.</p>',6))])}const b=n(d,[["render",l]]);export{f as __pageData,b as default};
